<?php require __DIR__.'/bootstrap.php';require __DIR__.'/layout.php';$u=require_admin();$message='';if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$target=(int)($_POST['user_id']??0);$q=$db->prepare('SELECT id,username,rol,activo FROM usuarios WHERE id=?');$q->execute([$target]);$before=$q->fetch();if($before&&$before['username']!=='DANFAR'){switch($_POST['action']??''){case 'toggle':$db->prepare('UPDATE usuarios SET activo=NOT activo WHERE id=?')->execute([$target]);audit($db,$u['id'],$u['username'],$before['activo']?'USER_DISABLED':'USER_ENABLED','USUARIO',$target,$before);break;case 'reset':$db->prepare("UPDATE usuarios SET password_hash=?,password_status='RESET_BY_ADMIN',password_changed_at=NOW(),password_changed_by=? WHERE id=?")->execute([password_hash('bkc#2026',PASSWORD_DEFAULT),$u['id'],$target]);audit($db,$u['id'],$u['username'],'PASSWORD_RESET','USUARIO',$target);break;case 'role':$role=in_array($_POST['role']??'', ['AGENTE','SUPERVISOR','ADMIN'],true)?$_POST['role']:'AGENTE';$db->prepare('UPDATE usuarios SET rol=? WHERE id=?')->execute([$role,$target]);audit($db,$u['id'],$u['username'],'ROLE_CHANGED','USUARIO',$target,$before,['rol'=>$role]);break;}$message='Cambio aplicado correctamente.';}}$users=$db->query('SELECT u.*,c.username changed_by_name FROM usuarios u LEFT JOIN usuarios c ON c.id=u.password_changed_by ORDER BY u.username')->fetchAll();$approvals=$db->query("SELECT a.*,c.nombre_completo,u.username FROM acuerdos a JOIN clientes c ON c.id=a.cliente_id JOIN usuarios u ON u.id=a.creado_por_id WHERE a.estado='PENDIENTE_APROBACION' ORDER BY a.created_at")->fetchAll();$auditRows=$db->query('SELECT username,accion,entidad,entidad_id,ip,created_at FROM auditoria ORDER BY id DESC LIMIT 100')->fetchAll();page_start('Administración',$u);if($message):?><div class="alert success"><?=e($message)?></div><?php endif?><section class="panel"><h2>Usuarios</h2><table><thead><tr><th>Usuario</th><th>Rol</th><th>Estado</th><th>Contraseña</th><th>Último cambio</th><th>Último acceso</th><th>Acciones</th></tr></thead><tbody><?php foreach($users as $r):?><tr><td><?=e($r['username'])?></td><td><?=e($r['rol'])?></td><td><?=$r['activo']?'Activo':'Inactivo'?></td><td><?=e($r['password_status'])?></td><td><?=e($r['password_changed_at']??'Sin cambios')?></td><td><?=e($r['last_login_at']??'Nunca')?></td><td><?php if($r['username']!=='DANFAR'):?><form method="post" class="row-actions"><input type="hidden" name="csrf" value="<?=csrf()?>"><input type="hidden" name="user_id" value="<?=$r['id']?>"><button name="action" value="toggle"><?=$r['activo']?'Desactivar':'Activar'?></button><button name="action" value="reset" data-confirm="¿Deseas restablecer la contraseña de <?=e($r['username'])?>?">Resetear contraseña</button><select name="role"><option>AGENTE</option><option>SUPERVISOR</option><option>ADMIN</option></select><button name="action" value="role">Cambiar rol</button></form><?php endif?></td></tr><?php endforeach?></tbody></table></section><section class="panel"><h2>Aprobaciones pendientes</h2><table><thead><tr><th>Agente</th><th>Cliente</th><th>Saldo</th><th>Monto</th><th>Descuento</th><th>Fecha</th></tr></thead><tbody><?php foreach($approvals as $r):?><tr><td><?=e($r['username'])?></td><td><?=e($r['nombre_completo'])?></td><td><?=money($r['saldo_negociado'])?></td><td><?=money($r['monto_acordado'])?></td><td><?=e($r['porcentaje_descuento'])?>%</td><td><?=e($r['created_at'])?></td></tr><?php endforeach?></tbody></table></section><section class="panel"><h2>Auditoría reciente</h2><table><thead><tr><th>Usuario</th><th>Acción</th><th>Entidad</th><th>IP</th><th>Fecha</th></tr></thead><tbody><?php foreach($auditRows as $r):?><tr><td><?=e($r['username'])?></td><td><?=e($r['accion'])?></td><td><?=e($r['entidad'])?> #<?=e((string)$r['entidad_id'])?></td><td><?=e($r['ip'])?></td><td><?=e($r['created_at'])?></td></tr><?php endforeach?></tbody></table></section><?php page_end();

